import { render, screen } from '@testing-library/react';
import { describe, it, expect } from 'vitest';
import UserStats from './UserStats';

describe('UserStats', () => {
  it('displays correct statistics for a mixed list of users', () => {
    const users = [
      { id: 1, name: 'Alice', isActive: true },
      { id: 2, name: 'Bob', isActive: false },
      { id: 3, name: 'Charlie', isActive: true },
    ];

    render(<UserStats users={users} />);

    // Check active users count
    expect(screen.getByText('Active Users: 2')).toBeDefined();

    // Check inactive users count
    expect(screen.getByText('Inactive Users: 1')).toBeDefined();

    // Check active percentage (2/3 * 100 = 66.666...)
    expect(screen.getByText(/Active Percentage: 66.7%/)).toBeDefined();
  });

  it('displays 0% when no users', () => {
    render(<UserStats users={[]} />);
    expect(screen.getByText('Active Users: 0')).toBeDefined();
    expect(screen.getByText('Inactive Users: 0')).toBeDefined();
    expect(screen.getByText('Active Percentage: 0.0%')).toBeDefined();
  });

  it('displays 100% when all users are active', () => {
    const users = [
      { id: 1, name: 'Alice', isActive: true },
      { id: 2, name: 'Bob', isActive: true },
    ];
    render(<UserStats users={users} />);
    expect(screen.getByText('Active Users: 2')).toBeDefined();
    expect(screen.getByText('Inactive Users: 0')).toBeDefined();
    expect(screen.getByText('Active Percentage: 100.0%')).toBeDefined();
  });
});

